// The only node you edit.
//
// Any retailer works. Keyword search is a different matter: a marketplace being
// on the Actor's supported list does not mean its search returns results, so
// pin product URLs rather than relying on search. See the README.
const WATCH = [
  'https://www.amazon.com/dp/REPLACE_ME',
  'https://www.walmart.com/ip/REPLACE_ME/000000000',
];
const SLACK_CHANNEL = '#pricing-alerts';

return [{ json: { detailsUrls: WATCH.map((url) => ({ url })), slackChannel: SLACK_CHANNEL } }];

// Normalize one Actor item per product into the row the database stores.
//
// Every retailer answers a slightly different shape. These are the three that
// actually corrupt data if you get them wrong, all seen in real responses:
//   price     a number on some retailers, a formatted string on others
//   currency  a symbol on some, an ISO code on others
//   brand     sometimes a string, sometimes an object, sometimes marketing text

// Parse a price without assuming a locale.
//
// Stripping everything except digits and dots works on US formatting and
// silently destroys European formatting: "1.299,99 EUR" becomes 1.29999 and
// "12,99 EUR" becomes 1299. Both write a plausible-looking wrong number, which
// is worse than failing.
//
// The rule: if both separators appear, the LAST one is the decimal separator.
// If only one appears, it is a decimal separator only when exactly two digits
// follow it and it occurs once.
const parsePrice = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) && v > 0 ? v : null;
  if (typeof v !== 'string') return null;

  // Drops currency symbols, ISO codes, and every kind of space including the
  // non-breaking and narrow no-break spaces used as thousands separators.
  let s = v.replace(/[^\d.,]/g, '');
  if (!s) return null;

  const lastDot = s.lastIndexOf('.');
  const lastComma = s.lastIndexOf(',');

  if (lastDot !== -1 && lastComma !== -1) {
    const decimalAt = Math.max(lastDot, lastComma);
    s = s.slice(0, decimalAt).replace(/[.,]/g, '') + '.' + s.slice(decimalAt + 1).replace(/[.,]/g, '');
  } else if (lastComma !== -1) {
    const tail = s.length - lastComma - 1;
    s = (tail === 2 && s.indexOf(',') === lastComma) ? s.replace(',', '.') : s.replace(/,/g, '');
  } else if (lastDot !== -1) {
    const tail = s.length - lastDot - 1;
    if (!(tail === 2 && s.indexOf('.') === lastDot)) s = s.replace(/\./g, '');
  }

  const n = Number.parseFloat(s);
  return Number.isFinite(n) && n > 0 ? n : null;
};

// Store ISO 4217, never the symbol. A row holding "$" cannot be compared with a
// row holding "$" from a different market, and the agent has no way to tell USD
// from CAD or AUD after the fact.
const SYMBOL_TO_ISO = {
  '$': 'USD', 'US$': 'USD', 'USD': 'USD',
  'C$': 'CAD', 'CA$': 'CAD', 'A$': 'AUD', 'AU$': 'AUD', 'NZ$': 'NZD',
  '€': 'EUR', '£': 'GBP', '¥': 'JPY', '₹': 'INR',
  'R$': 'BRL', 'Mex$': 'MXN', 'zł': 'PLN', 'Kč': 'CZK',
  'kr': 'SEK', 'CHF': 'CHF', '₩': 'KRW', '₽': 'RUB', '₺': 'TRY',
};

// A bare "$" is ambiguous. Fall back to the marketplace's home currency when the
// hostname says which market this is, rather than storing a symbol.
const HOST_TO_ISO = {
  'amazon.com': 'USD', 'walmart.com': 'USD', 'ebay.com': 'USD', 'target.com': 'USD',
  'amazon.ca': 'CAD', 'walmart.ca': 'CAD', 'bestbuy.ca': 'CAD',
  'amazon.com.au': 'AUD', 'amazon.co.uk': 'GBP', 'argos.co.uk': 'GBP',
  'amazon.de': 'EUR', 'amazon.fr': 'EUR', 'amazon.it': 'EUR', 'amazon.es': 'EUR',
  'amazon.nl': 'EUR', 'amazon.pl': 'PLN', 'allegro.pl': 'PLN', 'alza.cz': 'CZK',
};

const readCurrency = (item, extras, retailer) => {
  const offers = item.offers || {};
  const raw = String(offers.priceCurrency || offers.currency || extras.currencyRaw || '').trim();
  if (/^[A-Z]{3}$/.test(raw)) return raw;
  if (raw && SYMBOL_TO_ISO[raw]) {
    // Ambiguous dollar signs defer to the marketplace we are reading.
    if (raw === '$' && HOST_TO_ISO[retailer]) return HOST_TO_ISO[retailer];
    return SYMBOL_TO_ISO[raw];
  }
  return HOST_TO_ISO[retailer] || null;
};

// Read ONLY strings out of brand.
//
// Falling through to the object itself stringifies to "[object Object]", and it
// does so for the shapes that look harmless: {name: null} on eBay, and objects
// carrying only marketing text. Amazon uses brand.slogan for copy such as
// "Visit the Carhartt Store", so unwrap that and reject anything too long to be
// a brand name.
const readBrand = (item) => {
  const b = item.brand;
  let raw = '';
  if (typeof b === 'string') raw = b;
  else if (b && typeof b === 'object') {
    if (typeof b.name === 'string') raw = b.name;
    else if (typeof b.slogan === 'string') raw = b.slogan;
  }
  raw = raw.trim();
  if (!raw) return null;
  const unwrapped = raw.replace(/^Visit the (.+) Store$/i, '$1').trim();
  if (!unwrapped || unwrapped.length > 40 || unwrapped.split(/\s+/).length > 4) return null;
  return unwrapped;
};

// Stock is three-valued on purpose. Absent is not the same as out of stock, and
// several retailers simply do not report availability on a detail page.
const readStock = (item) => {
  const extras = item.additionalProperties || {};
  if (typeof extras.inStock === 'boolean') return extras.inStock;
  if (typeof item.inStock === 'boolean') return item.inStock;
  const avail = String((item.offers && item.offers.availability) || item.availability || '').toLowerCase();
  if (avail.includes('instock')) return true;
  if (avail.includes('outofstock')) return false;
  return null;
};

// The identity a SKU is tracked on has to be stable across days. Marketplaces
// append tracking and variant parameters that change per request, so the same
// product would otherwise arrive as a new sku_key and never build a baseline.
const canonicalUrl = (url) => {
  const s = String(url || '').trim();
  if (!s) return null;
  const withoutQuery = s.split('#')[0].split('?')[0];
  return withoutQuery.replace(/\/+$/, '') || null;
};

const rows = [];

for (const entry of $input.all()) {
  const item = entry.json || {};
  const offers = item.offers || {};
  const extras = item.additionalProperties || {};

  const url = canonicalUrl(item.url || item.inputUrl);
  // An unresolvable URL comes back as an item with every field empty rather
  // than as an error, so there is nothing to record.
  if (!url) continue;

  let retailer = null;
  const host = url.match(/^https?:\/\/([^/?#]+)/);
  if (host) retailer = host[1].replace(/^www\./, '').toLowerCase();

  rows.push({
    sku_key: url,
    product_url: url,
    retailer,
    product_name: String(item.name || item.title || '')
      .replace(/opens in a new (window or )?tab$/i, '')
      .trim() || null,
    brand: readBrand(item),
    price: parsePrice(offers.price !== undefined ? offers.price : offers.priceText),
    currency: readCurrency(item, extras, retailer),
    in_stock: readStock(item),
    image_url: item.image || null,
    raw: item,
  });
}

return [{ json: { rows } }];

// Fold every flagged product into one item, so the agent reasons once per run
// rather than once per product.
const moved = $input.all().map((i) => i.json);
return [{ json: { count: moved.length, moved: JSON.stringify(moved, null, 1) } }];

// Operational check, deliberately separate from the commercial alert.
//
// For a monitoring tool, "I received no data" must be an event. Without this the
// failure mode is silence: a page changes structure or starts blocking, the
// product quietly stops being recorded, and the first sign of trouble is a
// baseline that never fills. Silence looks identical to "nothing moved".
//
// This node returns NO items when every requested URL came back, which means the
// warning node after it is skipped. It returns one item only when something is
// missing, so a healthy run stays quiet by construction.

const canonical = (url) => {
  const s = String(url || '').trim();
  if (!s) return null;
  return s.split('#')[0].split('?')[0].replace(/\/+$/, '') || null;
};

const requested = ($('Select Pages to Monitor').first().json.detailsUrls || [])
  .map((d) => canonical(d.url))
  .filter(Boolean);

const rows = $input.first().json.rows || [];
const stored = new Set(rows.map((r) => r.sku_key));

const missing = requested.filter((url) => !stored.has(url));

// Recorded but with no usable price. The row exists, so the SKU is not missing,
// but it contributes nothing to a baseline and is worth knowing about.
const priceless = rows.filter((r) => r.price === null).map((r) => r.sku_key);

if (missing.length === 0 && priceless.length === 0) return [];

const lines = [
  `Collection warning: ${rows.length} of ${requested.length} watched products recorded.`,
];
if (missing.length) {
  lines.push('', `Returned nothing (${missing.length}):`);
  for (const url of missing.slice(0, 15)) lines.push(`  ${url}`);
  if (missing.length > 15) lines.push(`  and ${missing.length - 15} more`);
}
if (priceless.length) {
  lines.push('', `Recorded without a price (${priceless.length}):`);
  for (const url of priceless.slice(0, 15)) lines.push(`  ${url}`);
  if (priceless.length > 15) lines.push(`  and ${priceless.length - 15} more`);
}
lines.push(
  '',
  'This is a collection problem, not a pricing signal. Check whether the page still',
  'exists, whether its layout changed, or whether the run hit its time or cost cap.'
);

return [{
  json: {
    requested: requested.length,
    recorded: rows.length,
    missing,
    priceless,
    message: lines.join('\n'),
  },
}];
